const { SectionDAO } = require('../daos/sectionDAO');
const { AttachmentDAO } = require('../daos/attachmentDAO');
const { BinderDAO } = require('../daos');
const { generateUUID } = require('../utils/uuid');
const eventBus = require('../events/eventBus');
const pool = require('../../config/db');
const withTransaction = require('../core/withTransaction');
const { NotFoundError, BadRequestError, ForbiddenError } = require('../core/errors');
const { TargetType, ActionType } = require('../utils/typeDefinitions');

class SectionService {
  async getSectionByBinderId(binderId, userId) {
    const member = await BinderDAO.getMember(pool, binderId, userId);
    if (!member || member.deleted_at) throw new ForbiddenError('바인더 멤버만 섹션을 조회할 수 있습니다');
    return await SectionDAO.findByBinderId(pool, binderId, userId);
  }

  async createSection(data, context) {
    const section = await withTransaction(async (client) => {
      const actor = await BinderDAO.getMember(client, data.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      if (Object.prototype.hasOwnProperty.call(data, 'group_id')) throw new BadRequestError('group_id는 지원하지 않습니다');
      const scope = data.access_scope ?? 0;
      if (![0, 1].includes(scope)) throw new BadRequestError('access_scope는 0 또는 1이어야 합니다');
      const created = await SectionDAO.create(client, {
        id: data.id || generateUUID(),
        binder_id: data.binder_id,
        title: data.title,
        access_scope: scope,
      });
      if (scope === 1) await SectionDAO.addMember(client, created.id, context.sender_id, generateUUID());
      return created;
    });

    eventBus.emit('sync', {
      binder_id: data.binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.CREATE, target_type: TargetType.SECTION, target_id: section.id,
    });

    return section;
  }

  async updateSection(sectionId, updateData, context) {
    const { section, result } = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId, true);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      if (Object.keys(updateData).some((key) => key !== 'title')) {
        throw new BadRequestError('수정 가능한 필드는 title뿐입니다');
      }
      const result = await SectionDAO.update(client, sectionId, updateData);
      return { section, result };
    });

    eventBus.emit('sync', {
      binder_id: section.binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.UPDATE, target_type: TargetType.SECTION, target_id: sectionId,
    });

    return result;
  }

  async deleteSection(sectionId, context) {
    const { binder_id } = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      if (section.is_default) throw new BadRequestError('기본 섹션은 삭제할 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');

      await SectionDAO.softDelete(client, sectionId);
      return { binder_id: section.binder_id };
    });

    eventBus.emit('sync', {
      binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.DELETE, target_type: TargetType.SECTION, target_id: sectionId,
    });
  }

  async addMembers(sectionId, userIds, context) {
    if (!Array.isArray(userIds) || userIds.length === 0) throw new BadRequestError('user_ids 배열이 필요합니다');
    const uniqueUserIds = [...new Set(userIds)];
    const result = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId, true);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      if (section.access_scope !== 1) throw new BadRequestError('public 섹션에는 멤버를 추가할 수 없습니다');
      const added = [];
      for (const userId of uniqueUserIds) {
        const target = await BinderDAO.getMember(client, section.binder_id, userId);
        if (!target || target.deleted_at) throw new BadRequestError('모든 user_id는 활성 바인더 멤버여야 합니다');
        if (await SectionDAO.addMember(client, sectionId, userId, generateUUID())) added.push(userId);
      }
      return { binderId: section.binder_id, added_user_ids: added, member_count: await SectionDAO.countMembers(client, sectionId) };
    });
    eventBus.emit('sync', { binder_id: result.binderId, sender_id: context.sender_id, device_uuid: context.device_uuid,
      action: ActionType.UPDATE, target_type: TargetType.SECTION, target_id: sectionId });
    return { added_user_ids: result.added_user_ids, member_count: result.member_count };
  }

  async removeMember(sectionId, userId, context) {
    const result = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId, true);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      if (section.access_scope !== 1) throw new BadRequestError('public 섹션에는 멤버가 없습니다');
      await SectionDAO.removeMember(client, sectionId, userId);
      const memberCount = await SectionDAO.countMembers(client, sectionId);
      const sectionDeleted = memberCount === 0 ? await SectionDAO.softDelete(client, sectionId) : false;
      return { binderId: section.binder_id, removed_user_id: userId, member_count: memberCount, section_deleted: sectionDeleted };
    });
    eventBus.emit('sync', { binder_id: result.binderId, sender_id: context.sender_id, device_uuid: context.device_uuid,
      action: ActionType.UPDATE, target_type: TargetType.SECTION, target_id: sectionId });
    return { removed_user_id: result.removed_user_id, member_count: result.member_count, section_deleted: result.section_deleted };
  }

  async listFiles(sectionId, query, userId) {
    const section = await SectionDAO.findById(pool, sectionId);
    if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');

    await this.assertContentAccess(sectionId, userId);

    return await AttachmentDAO.findBySection(pool, sectionId, query);
  }

  async assertContentAccess(sectionId, userId) {
    if (!(await SectionDAO.hasAccess(pool, sectionId, userId))) throw new ForbiddenError('섹션 콘텐츠 접근 권한이 없습니다', 'SECTION_ACCESS_DENIED');
  }

  async assertMessageAccess(messageId, userId) {
    const sectionId = await SectionDAO.findSectionIdByMessage(pool, messageId);
    if (!sectionId) throw new NotFoundError('메시지를 찾을 수 없습니다');
    return this.assertContentAccess(sectionId, userId);
  }

}

module.exports = { SectionService: new SectionService() };
class SectionDAO {
  async findById(conn, sectionId, lock = false) {
    const { rows } = await conn.query(
      `SELECT id, binder_id, title, access_scope, is_default, created_at, updated_at, deleted_at
       FROM sections WHERE id = $1 AND deleted_at IS NULL ${lock ? 'FOR UPDATE' : ''}`, [sectionId]
    );
    return rows[0] || null;
  }

  async findByBinderId(conn, binderId, userId) {
    const { rows } = await conn.query(
      `SELECT s.id, s.binder_id, s.title, s.access_scope, s.is_default,
              s.created_at, s.updated_at,
              CASE WHEN s.access_scope = 1 THEN
                (SELECT COUNT(*)::int FROM section_members sm
                 WHERE sm.section_id = s.id AND sm.deleted_at IS NULL)
              ELSE NULL END AS member_count,
              CASE WHEN s.access_scope = 0 OR EXISTS (
                SELECT 1 FROM section_members sm
                WHERE sm.section_id = s.id AND sm.user_id = $2 AND sm.deleted_at IS NULL
              ) THEN TRUE ELSE FALSE END AS "canAccessContent"
       FROM sections s
       WHERE s.binder_id = $1 AND s.deleted_at IS NULL
         AND (s.access_scope = 0 OR EXISTS (
           SELECT 1 FROM section_members sm
           WHERE sm.section_id = s.id AND sm.user_id = $2 AND sm.deleted_at IS NULL
         ) OR EXISTS (
           SELECT 1 FROM binder_members bm WHERE bm.binder_id = s.binder_id AND bm.user_id = $2
             AND bm.role <= 1 AND bm.deleted_at IS NULL
         )) ORDER BY s.is_default DESC, s.created_at`, [binderId, userId]
    );
    return rows;
  }

  async create(conn, { id, binder_id, title, access_scope = 0 }) {
    const { rows } = await conn.query(
      `INSERT INTO sections (id, binder_id, title, access_scope, created_at, updated_at)
       VALUES ($1, $2, $3, $4, now(), now())
       RETURNING id, binder_id, title, access_scope, is_default, created_at, updated_at`,
      [id, binder_id, title, access_scope]
    );
    return rows[0];
  }

  async update(conn, sectionId, { title }) {
    const { rows } = await conn.query(
      `UPDATE sections SET title = COALESCE($1, title), updated_at = now()
       WHERE id = $2 AND deleted_at IS NULL
       RETURNING id, binder_id, title, access_scope, is_default, created_at, updated_at`,
      [title, sectionId]
    );
    return rows[0] || null;
  }

  async hasAccess(conn, sectionId, userId) {
    const { rowCount } = await conn.query(
      `SELECT 1 FROM sections s
       JOIN binder_members bm ON bm.binder_id = s.binder_id AND bm.user_id = $2 AND bm.deleted_at IS NULL
       WHERE s.id = $1 AND s.deleted_at IS NULL AND (s.access_scope = 0 OR EXISTS (
         SELECT 1 FROM section_members sm
         WHERE sm.section_id = s.id AND sm.user_id = $2 AND sm.deleted_at IS NULL))`,
      [sectionId, userId]
    );
    return rowCount > 0;
  }

  async addMember(conn, sectionId, userId, id) {
    const { rows } = await conn.query(
      `WITH restored AS (
         UPDATE section_members SET deleted_at = NULL, updated_at = now()
         WHERE id = (SELECT id FROM section_members
           WHERE section_id = $1 AND user_id = $2 AND deleted_at IS NOT NULL
           ORDER BY updated_at DESC LIMIT 1 FOR UPDATE)
         RETURNING user_id
       ), inserted AS (
         INSERT INTO section_members (id, section_id, user_id)
         SELECT $3, $1, $2 WHERE NOT EXISTS (SELECT 1 FROM restored)
           AND NOT EXISTS (SELECT 1 FROM section_members
             WHERE section_id = $1 AND user_id = $2 AND deleted_at IS NULL)
         ON CONFLICT (section_id, user_id) WHERE deleted_at IS NULL DO NOTHING
         RETURNING user_id
       ) SELECT user_id FROM restored UNION ALL SELECT user_id FROM inserted`,
      [sectionId, userId, id]
    );
    return rows.length > 0;
  }

  async removeMember(conn, sectionId, userId) {
    const { rowCount } = await conn.query(
      `UPDATE section_members SET deleted_at = now(), updated_at = now()
       WHERE section_id = $1 AND user_id = $2 AND deleted_at IS NULL`,
      [sectionId, userId]
    );
    return rowCount > 0;
  }

  async countMembers(conn, sectionId) {
    const { rows } = await conn.query(
      `SELECT COUNT(*)::int AS count FROM section_members
       WHERE section_id = $1 AND deleted_at IS NULL`, [sectionId]
    );
    return rows[0].count;
  }

  async findSectionIdByMessage(conn, messageId) {
    const { rows } = await conn.query(`SELECT section_id FROM section_messages WHERE id = $1 AND deleted_at IS NULL`, [messageId]);
    return rows[0]?.section_id || null;
  }

  async softDelete(conn, sectionId) {
    await conn.query(
      `UPDATE attachments a SET deleted_at = now(), updated_at = now(), status = 'deleted'
       WHERE a.context_type = 'SECTION_MESSAGE' AND a.deleted_at IS NULL AND EXISTS (
         SELECT 1 FROM section_messages m WHERE m.id = a.context_id AND m.section_id = $1)`, [sectionId]
    );
    for (const table of ['message_embeds', 'message_reactions', 'message_mentions']) {
      await conn.query(
        `UPDATE ${table} child SET deleted_at = now(), updated_at = now()
         WHERE child.deleted_at IS NULL AND EXISTS (
           SELECT 1 FROM section_messages m WHERE m.id = child.message_id AND m.section_id = $1)`, [sectionId]
      );
    }
    await conn.query(`UPDATE section_messages SET deleted_at = now(), updated_at = now() WHERE section_id = $1 AND deleted_at IS NULL`, [sectionId]);
    await conn.query(`UPDATE event_sections SET deleted_at = now(), updated_at = now() WHERE section_id = $1 AND deleted_at IS NULL`, [sectionId]);
    await conn.query(`UPDATE task_sections SET deleted_at = now(), updated_at = now() WHERE section_id = $1 AND deleted_at IS NULL`, [sectionId]);
    await conn.query(
      `UPDATE section_members SET deleted_at = now(), updated_at = now()
       WHERE section_id = $1 AND deleted_at IS NULL`, [sectionId]
    );
    const { rowCount } = await conn.query(
      `UPDATE sections SET deleted_at = now(), updated_at = now()
       WHERE id = $1 AND deleted_at IS NULL AND is_default = FALSE`, [sectionId]
    );
    return rowCount > 0;
  }
}

module.exports = { SectionDAO: new SectionDAO() };
const { SectionService } = require('../../services/sectionService');
const { MessageService } = require('../../services/messageService');
const { MessageDAO } = require('../../daos/messageDAO');
const pool = require('../../../config/db');
const asyncHandler = require('../../core/asyncHandler');

const sectionController = {
  // ============================================
  // Section CRUD
  // ============================================

  getSection: asyncHandler(async (req, res) => {
    const { binderId } = req.params;
    const section = await SectionService.getSectionByBinderId(binderId, req.user_id);
    res.json({ success: true, data: section });
  }),

  createSection: asyncHandler(async (req, res) => {
    const section = await SectionService.createSection(req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.status(201).json({ success: true, data: section, message: '섹션이 생성되었습니다' });
  }),

  updateSection: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const section = await SectionService.updateSection(sectionId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: section, message: '섹션이 수정되었습니다' });
  }),

  deleteSection: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.deleteSection(sectionId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, message: '섹션이 삭제되었습니다' });
  }),

  addMembers: asyncHandler(async (req, res) => {
    const result = await SectionService.addMembers(req.params.sectionId, req.body.user_ids,
      { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.status(201).json({ success: true, data: result });
  }),

  removeMember: asyncHandler(async (req, res) => {
    const result = await SectionService.removeMember(req.params.sectionId, req.params.userId,
      { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: result });
  }),

  // ============================================
  // Messages
  // ============================================

  getMessages: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const { cursor_at, cursor_id, before_cursor, limit } = req.query;
    const parsedLimit = limit ? parseInt(limit, 10) : undefined;

    let cursorAt = cursor_at;
    let cursorId = cursor_id;

    if (before_cursor && !cursor_at) {
      const cursorMsg = await MessageDAO.findById(pool, before_cursor);
      if (cursorMsg) {
        cursorAt = cursorMsg.created_at;
        cursorId = cursorMsg.id;
      }
    }

    await SectionService.assertContentAccess(sectionId, req.user_id);
    const messages = await MessageService.getMessages(sectionId, {
      cursor_at: cursorAt, cursor_id: cursorId, limit: parsedLimit,
    });
    res.json({ success: true, data: messages });
  }),

  createMessage: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    const message = await MessageService.createMessage(sectionId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.status(201).json({ success: true, data: message, message: '메시지가 생성되었습니다' });
  }),

  updateMessage: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const message = await MessageService.updateMessage(messageId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: message, message: '메시지가 수정되었습니다' });
  }),

  deleteMessage: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.deleteMessage(messageId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, message: '메시지가 삭제되었습니다' });
  }),

  togglePin: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const result = await MessageService.togglePin(messageId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: result, message: '핀 상태가 변경되었습니다' });
  }),

  // ============================================
  // Files
  // ============================================

  listFiles: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const files = await SectionService.listFiles(sectionId, req.query, req.user_id);
    res.json({ success: true, data: files });
  }),

  // ============================================
  // Reactions
  // ============================================

  addReaction: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    const { emoji } = req.body;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const result = await MessageService.addReaction(messageId, emoji, { sender_id: req.user_id });
    res.status(201).json({ success: true, data: result });
  }),

  removeReaction: asyncHandler(async (req, res) => {
    const { messageId, emoji } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.removeReaction(messageId, emoji, { sender_id: req.user_id });
    res.json({ success: true, message: '리액션이 제거되었습니다' });
  }),

  // ============================================
  // Cursor (읽음 위치)
  // ============================================

  updateCursor: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    await MessageService.updateCursor(sectionId, req.user_id, req.body);
    res.json({ success: true });
  }),

  // ============================================
  // Pinned Messages
  // ============================================

  getPinnedMessages: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    const messages = await MessageService.getPinnedMessages(sectionId);
    res.json({ success: true, data: messages });
  }),

  // ============================================
  // Polls
  // ============================================

  getPoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const poll = await MessageService.getPoll(messageId, pollId, req.user_id);
    res.json({ success: true, data: poll });
  }),

  votePoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.votePoll(messageId, pollId, req.body, req.user_id);
    res.json({ success: true });
  }),

  closePoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.closePoll(messageId, pollId, { sender_id: req.user_id });
    res.json({ success: true });
  }),
};

module.exports = sectionController;
const express = require("express");
const router = express.Router();
const sectionController = require("../api/sections/sectionController");

router.route("/:sectionId")
  .patch(sectionController.updateSection)
  .delete(sectionController.deleteSection);

router.post("/:sectionId/members", sectionController.addMembers);
router.delete("/:sectionId/members/:userId", sectionController.removeMember);

// Cursor (읽음 위치 갱신)
router.put("/:sectionId/cursor", sectionController.updateCursor);

// Pinned Messages — /:sectionId/messages/:messageId 보다 앞에 등록
router.get("/:sectionId/messages/pinned", sectionController.getPinnedMessages);

// Messages
router.route("/:sectionId/messages")
  .get(sectionController.getMessages)
  .post(sectionController.createMessage);

router.route("/:sectionId/messages/:messageId")
  .patch(sectionController.updateMessage)
  .delete(sectionController.deleteMessage);

router.patch("/:sectionId/messages/:messageId/pin", sectionController.togglePin);

// Files
router.get("/:sectionId/files", sectionController.listFiles);

// Reactions
router.post("/:sectionId/messages/:messageId/reactions", sectionController.addReaction);
router.delete("/:sectionId/messages/:messageId/reactions/:emoji", sectionController.removeReaction);

// Polls
router.get("/:sectionId/messages/:messageId/polls/:pollId", sectionController.getPoll);
router.post("/:sectionId/messages/:messageId/polls/:pollId/vote", sectionController.votePoll);
router.patch("/:sectionId/messages/:messageId/polls/:pollId/close", sectionController.closePoll);

module.exports = router;
const express = require("express");
const router = express.Router();
const binderController = require("../api/binders/binderController");
const postController = require("../api/posts/postController");
const calendarController = require("../api/calendars/calendarController");
const sectionController = require("../api/sections/sectionController");
const asyncHandler = require('../core/asyncHandler');
const { GroupService } = require('../services/groupService');

// 검색 / 생성
router.get("/", binderController.searchBinders);
router.post("/", binderController.createBinder);

// 초대 토큰으로 가입 (POST /binders/join — /invitations/:code 보다 앞에)
router.post("/join", binderController.joinBinderByInvitation);

// 초대 미리보기 (/:binderId 보다 앞에 등록)
