        OR
        (s.binder_id = ANY($3::uuid[]) AND m.deleted_at IS NULL AND m.created_at >= $4)
        OR
        (s.id = ANY($6::uuid[]) AND m.deleted_at IS NULL AND m.created_at >= $4)
      )
      ORDER BY m.created_at DESC
    `;
    const { rows } = await pool.query(query, [
